// ============================================================
// ERROR RECOVERY & OFFLINE RESILIENCE (v3.87)
// ============================================================

var _isOnline = navigator.onLine;
var _offlineBanner: HTMLElement | null = null;
var _retryQueue: Array<{ fn: () => Promise<unknown>; label: string }> = [];

/** Check if the browser is online */
function isOnline(): boolean { return _isOnline; }

/** Initialize offline/online detection */
function initOfflineDetection(): void {
  window.addEventListener('online', function() {
    _isOnline = true;
    console.log('[BJ] Back online');
    _hideOfflineBanner();
    _drainRetryQueue();
  });
  window.addEventListener('offline', function() {
    _isOnline = false;
    console.warn('[BJ] Went offline');
    _showOfflineBanner();
  });
}

function _showOfflineBanner(): void {
  if (_offlineBanner) return;
  _offlineBanner = document.createElement('div');
  _offlineBanner.id = 'bj-offline-banner';
  _offlineBanner.style.cssText = 'position:fixed;top:0;left:0;right:0;z-index:99999;background:#f59e0b;color:#000;text-align:center;padding:8px 16px;font-size:14px;font-weight:600;';
  _offlineBanner.textContent = 'You are offline — changes will sync when connection returns';
  document.body.prepend(_offlineBanner);
}

function _hideOfflineBanner(): void {
  if (_offlineBanner) { _offlineBanner.remove(); _offlineBanner = null; }
}

/** Retry a failed async operation with exponential backoff */
async function withRetry<T>(fn: () => Promise<T>, opts?: { retries?: number; delay?: number; label?: string }): Promise<T> {
  var maxRetries = (opts && opts.retries) || 3;
  var baseDelay = (opts && opts.delay) || 1000;
  var label = (opts && opts.label) || 'operation';

  for (var attempt = 0; attempt <= maxRetries; attempt++) {
    try {
      return await fn();
    } catch (e: unknown) {
      if (attempt === maxRetries) {
        reportError('globals', e);
        console.error('[BJ] ' + label + ' failed after ' + (maxRetries + 1) + ' attempts:', (e as Error).message);
        throw e;
      }
      var delay = baseDelay * Math.pow(2, attempt) + Math.random() * 500;
      reportError('globals', e);
      console.warn('[BJ] ' + label + ' attempt ' + (attempt + 1) + ' failed, retrying in ' + Math.round(delay) + 'ms');
      await new Promise(function(resolve) { setTimeout(resolve, delay); });
    }
  }
}

/** Queue a failed write operation for retry when back online */
function queueForRetry(fn: () => Promise<unknown>, label: string): void {
  _retryQueue.push({ fn: fn, label: label || 'queued op', addedAt: Date.now() });
  console.log('[BJ] Queued for retry: ' + label + ' (' + _retryQueue.length + ' pending)');
}

/** Drain the retry queue (called when coming back online) */
async function _drainRetryQueue(): Promise<void> {
  if (_retryQueue.length === 0) return;
  console.log('[BJ] Draining retry queue: ' + _retryQueue.length + ' items');
  var queue = _retryQueue.slice();
  _retryQueue = [];
  for (var i = 0; i < queue.length; i++) {
    try {
      await queue[i].fn();
      console.log('[BJ] Retry succeeded: ' + queue[i].label);
    } catch (e: unknown) {
      reportError('globals', e);
      console.warn('[BJ] Retry failed: ' + queue[i].label, (e as Error).message);
      // Don't re-queue items older than 10 minutes
      if (Date.now() - queue[i].addedAt < 600000) {
        _retryQueue.push(queue[i]);
      }
    }
  }
}

/** Global unhandled error and rejection handlers */
// BE-005: Throttle for network error toasts to avoid spam
var _lastNetworkToastTime = 0;
var _NETWORK_TOAST_THROTTLE_MS = 10000; // 10s between network error toasts

function initGlobalErrorHandlers(): void {
  window.addEventListener('error', function(event) {
    console.error('[BJ] Uncaught error:', event.message, 'at', event.filename + ':' + event.lineno);
  });

  window.addEventListener('unhandledrejection', function(event) {
    var reason = event.reason;
    var msg = reason && reason.message ? reason.message : String(reason);
    // BE-005: Network errors are no longer silently suppressed.
    // Offline: report to PostHog (offline banner already visible via initOfflineDetection).
    // Online: report to PostHog + show user-facing toast with retry guidance.
    if (msg.includes('Failed to fetch') || msg.includes('NetworkError') || msg.includes('Load failed')) {
      reportError('network', reason, { online: _isOnline, handler: 'unhandledrejection' });
      if (!_isOnline) {
        // Offline banner already handles user notification — just log, don't toast-spam
        console.warn('[BJ] Network error while offline (reported):', msg);
        event.preventDefault();
        return;
      }
      // Online but network failed — surface to user with throttle
      var now = Date.now();
      if (now - _lastNetworkToastTime > _NETWORK_TOAST_THROTTLE_MS) {
        _lastNetworkToastTime = now;
        toastWarning('Network request failed — check your connection and try again.', {
          duration: 6000,
          action: { label: 'Retry', fn: function() { window.location.reload(); } }
        });
      }
      console.warn('[BJ] Network error while online (reported + user notified):', msg);
      return;
    }
    console.error('[BJ] Unhandled promise rejection:', msg);
  });
}

/** Safe Supabase query wrapper — handles offline, retries, fallback */
// ── DO-001: Error reporting + persistent monitoring ──
var _errorBatch: Array<Record<string, unknown>> = [];
var _errorFlushTimer: ReturnType<typeof setTimeout> | null = null;
var _ERROR_BATCH_MAX = 10;
var _ERROR_FLUSH_MS = 5000;
var _errorDedup: Record<string, number> = {};
var _ERROR_DEDUP_WINDOW_MS = 60000; // suppress same fingerprint for 60s

function _errorFingerprint(label: string, msg: string): string {
  // Simple hash: first 8 chars of label + first 60 chars of message
  return (label + ':' + (msg || '').slice(0, 60)).replace(/\s+/g, ' ');
}

function _flushErrorBatch(): void {
  if (_errorBatch.length === 0) return;
  var batch = _errorBatch.splice(0, _ERROR_BATCH_MAX);
  _errorFlushTimer = null;
  try {
    // Fire-and-forget insert — never block the app
    sb.from('client_errors').insert(batch).then(function(result: { error?: { message?: string } }) {
      if (result.error) {
        console.warn('[BJ] Error batch insert failed:', result.error.message);
      }
    });
  } catch (_) { /* never let monitoring break the app */ }
}

function reportError(label: string, error: unknown, extra?: Record<string, unknown>): void {
  var msg = error && (error as Error).message ? (error as Error).message : String(error);
  console.warn('[BJ] ' + label + ' failed:', msg);

  // PostHog (existing analytics)
  try {
    if (window.posthog) {
      posthog.capture('query_error', {
        label: label,
        error_message: msg,
        error_stack: error && (error as Error).stack ? (error as Error).stack!.slice(0, 500) : undefined,
        page: window.location.pathname,
        timestamp: new Date().toISOString(),
        ...(extra || {})
      });
    }
  } catch (_) { /* never let reporting break the app */ }

  // Persistent error logging (DO-001)
  try {
    var fp = _errorFingerprint(label, msg);
    var now = Date.now();
    // Dedup: skip if we logged the same fingerprint in the last 60s
    if (_errorDedup[fp] && (now - _errorDedup[fp]) < _ERROR_DEDUP_WINDOW_MS) return;
    _errorDedup[fp] = now;
    // Clean old dedup entries every ~50 errors
    if (Object.keys(_errorDedup).length > 50) {
      for (var k in _errorDedup) {
        if (now - _errorDedup[k] > _ERROR_DEDUP_WINDOW_MS) delete _errorDedup[k];
      }
    }

    var severity = label.includes('fatal') ? 'fatal' : label.includes('silent') || label.includes('ignore') ? 'warning' : 'error';
    _errorBatch.push({
      user_id: (typeof currentUser !== 'undefined' && currentUser) ? currentUser.id : null,
      surface: 'dashboard',
      label: label,
      message: msg.slice(0, 2000),
      stack: error && (error as Error).stack ? (error as Error).stack!.slice(0, 4000) : null,
      url: window.location.href,
      page: (typeof localStorage !== 'undefined' ? localStorage.getItem('bj_active_tab') : null) || 'unknown',
      version: typeof BJ_VERSION !== 'undefined' ? BJ_VERSION : 'unknown',
      user_agent: navigator.userAgent.slice(0, 500),
      metadata: extra || {},
      severity: severity,
      fingerprint: fp
    });

    // Flush when batch is full or schedule a delayed flush
    if (_errorBatch.length >= _ERROR_BATCH_MAX) {
      _flushErrorBatch();
    } else if (!_errorFlushTimer) {
      _errorFlushTimer = setTimeout(_flushErrorBatch, _ERROR_FLUSH_MS);
    }
  } catch (_) { /* never let monitoring break the app */ }
}

// Flush errors on page unload
if (typeof window !== 'undefined') {
  window.addEventListener('beforeunload', function() {
    if (_errorBatch.length > 0) _flushErrorBatch();
    // Flush pending user data to Supabase before page close (prevents PII data loss)
    if (_udPendingKeys.size > 0 && typeof _flushUserData === 'function') _flushUserData();
  });
  // Also flush when tab becomes hidden (more reliable for async ops than beforeunload)
  document.addEventListener('visibilitychange', function() {
    if (document.hidden && _udPendingKeys.size > 0 && typeof _flushUserData === 'function') _flushUserData();
  });
}

async function safeQuery(queryFn: () => Promise<unknown>, opts?: SafeQueryOptions): Promise<unknown> {
  var label = (opts && opts.label) || 'query';
  var fallback = opts && opts.fallback;
  var retry = opts && opts.retry !== false;
  var silent = opts && opts.silent;

  if (!_isOnline) {
    console.warn('[BJ] Offline — skipping ' + label);
    return fallback !== undefined ? fallback : null;
  }

  try {
    if (retry) {
      return await withRetry(function() {
        return queryFn().then(function(result) {
          if (result.error) throw new Error(result.error.message);
          return result.data;
        });
      }, { retries: 2, delay: 800, label: label });
    } else {
      var result = await queryFn();
      if (result.error) throw new Error(result.error.message);
      return result.data;
    }
  } catch (e: unknown) {
    if (!silent) reportError(label, e);
    return fallback !== undefined ? fallback : null;
  }
}

// ── Convenience wrapper: safeRpc ──
async function safeRpc(fnName: string, params?: Record<string, unknown>, opts?: SafeQueryOptions): Promise<unknown> {
  var label = (opts && opts.label) || ('rpc:' + fnName);
  return safeQuery(function() { return sb.rpc(fnName, params); }, { ...opts, label: label });
}


// === js/theme.js ===
/* ──────────────────────────────────────────────────────────
   Brilliant Jobs — Theme Toggle (CS-P1-009: CSS-002)
   
   Modes: light | dark | auto (follows OS preference)
   Persists to localStorage. Applied before first paint via
   inline script in <head> to prevent flash of wrong theme.
   ────────────────────────────────────────────────────────── */

(function() {
  'use strict';

  var STORAGE_KEY = 'bj-theme';
  var VALID_THEMES = ['light', 'dark', 'auto'];
  var ICON_SUN = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="theme-toggle-icon"><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="4.22"/></svg>';
  var ICON_MOON = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="theme-toggle-icon"><path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z"/></svg>';
  var ICON_AUTO = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="theme-toggle-icon"><circle cx="12" cy="12" r="10"/><path d="M12 2a10 10 0 0 1 0 20V2z"/></svg>';

  var LABELS = { light: 'Light', dark: 'Dark', auto: 'Auto' };
  var ICONS = { light: ICON_SUN, dark: ICON_MOON, auto: ICON_AUTO };

  function getStoredTheme() {
    try {
      var stored = localStorage.getItem(STORAGE_KEY);
      return VALID_THEMES.indexOf(stored) !== -1 ? stored : 'auto';
    } catch (e) {
      return 'auto';
    }
  }

  function setStoredTheme(theme) {
    try { localStorage.setItem(STORAGE_KEY, theme); } catch (e) { /* storage blocked */ }
  }

  function applyTheme(theme) {
    document.documentElement.setAttribute('data-theme', theme);
    // Update toggle buttons if they exist
    var toggles = document.querySelectorAll('.theme-toggle');
    toggles.forEach(function(el) {
      el.innerHTML = ICONS[theme] + '<span class="theme-toggle-label">' + LABELS[theme] + '</span>';
      el.setAttribute('title', 'Theme: ' + LABELS[theme] + ' (click to cycle)');
    });
    // Track with PostHog if available
    if (window.posthog && typeof window.posthog.capture === 'function') {
      window.posthog.capture('theme_changed', { theme: theme });
    }
  }

  function cycleTheme() {
    var current = getStoredTheme();
    var order = ['light', 'dark', 'auto'];
    var next = order[(order.indexOf(current) + 1) % order.length];
    setStoredTheme(next);
    applyTheme(next);
  }

  // Apply on load
  var theme = getStoredTheme();
  applyTheme(theme);

  // Expose for nav toggle button
  window.BJ_Theme = {
    cycle: cycleTheme,
    get: getStoredTheme,
    set: function(t) { if (VALID_THEMES.indexOf(t) !== -1) { setStoredTheme(t); applyTheme(t); } }
  };

  // Listen for OS preference changes when in auto mode
  if (window.matchMedia) {
    window.matchMedia('(prefers-color-scheme: dark)').addEventListener('change', function() {
      if (getStoredTheme() === 'auto') {
        applyTheme('auto');
      }
    });
  }
})();


// === js/sync.ts ===
// ============================================================
// SYNC HEALTH CHECK — Safety net for localStorage ↔ Supabase consistency
// CS-P1-015: TypeScript strict mode
// ============================================================

async function syncHealthCheck(): Promise<void> {
  if (typeof sb === 'undefined' || typeof currentUser === 'undefined' || !currentUser) return;
  console.log('[sync] Running health check...');

  var UD_KEYS: Record<string, string> = {
    saved_filters: 'bj_saved_filters',
    resumes: 'bj_resumes',
    pipeline_meta: 'bj_pipeline_meta',
    tuning: 'bj_tuning',
    saved_jobs: 'bj_saved_jobs',
    applied_jobs: 'bj_applied_jobs',
    applied_dates: 'bj_applied_dates',
    hidden_jobs: 'bj_hidden_jobs',
    app_queue: 'bj_app_queue',
    app_history: 'bj_app_history',
    readiness: 'bj_readiness'
  };

  var GLOBALS_MAP: Record<string, string> = {
    saved_filters: 'savedFilters',
    resumes: 'resumes',
    tuning: 'tuningSettings',
    hidden_jobs: 'hiddenJobIds',
    saved_jobs: 'savedJobIds',
    applied_jobs: 'appliedJobIds',
    applied_dates: 'appliedDates',
    readiness: 'readinessCache',
    app_queue: 'appQueue',
    app_history: 'appHistory',
  };

  var missing: string[] = [];
  for (var _shortKey of Object.keys(UD_KEYS)) {
    var lsKey = UD_KEYS[_shortKey]!;
    try {
      var raw = localStorage.getItem(lsKey);
      var parsed: unknown = raw ? JSON.parse(raw) : null;
      var empty = parsed == null ||
        (Array.isArray(parsed) && parsed.length === 0) ||
        (typeof parsed === 'object' && !Array.isArray(parsed) && Object.keys(parsed as Record<string, unknown>).length === 0);
      if (empty) missing.push(_shortKey);
    } catch { missing.push(_shortKey); }
  }

  if (missing.length === 0) {
    console.log('[sync] Health check passed — all data present');
    return;
  }

  console.log('[sync] Missing:', missing.join(', '), '— recovering from cloud');

  try {
    var result = await (sb as SupabaseClient).from('profiles')
      .select('user_data')
      .eq('id', currentUser.id)
      .single();

    var data = result.data as Record<string, unknown> | null;
    var error = result.error;

    if (!error && data?.user_data) {
      var cloud = data.user_data as Record<string, unknown>;
      localStorage.setItem('_bj_ud_cache', JSON.stringify(cloud));

      for (var shortKey of missing) {
        var lsKeyRecover = UD_KEYS[shortKey]!;
        var cloudVal = cloud[shortKey] as unknown;
        if (cloudVal != null) {
          var isNotEmpty = Array.isArray(cloudVal) ? cloudVal.length > 0 :
            typeof cloudVal === 'object' ? Object.keys(cloudVal as Record<string, unknown>).length > 0 : true;
          if (isNotEmpty) {
            localStorage.setItem(lsKeyRecover, JSON.stringify(cloudVal));
            var globalName = GLOBALS_MAP[shortKey];
            if (globalName && typeof (window as Record<string, unknown>)[globalName] !== 'undefined') {
              (window as Record<string, unknown>)[globalName] = cloudVal;
            }
            console.log('[sync] Recovered', shortKey, 'from cloud');
          }
        }
      }
    }
  } catch (e: unknown) {
    reportError('sync', e);
    console.warn('[sync] Health check cloud fetch error:', (e as Error).message);
  }

  if (missing.includes('saved_filters')) {
    try {
      var filterResult = await (sb as SupabaseClient).from('user_filters')
        .select('*').eq('user_id', currentUser.id).order('sort_order');
      var filters = filterResult.data as Array<Record<string, unknown>> | null;
      if (filters && filters.length > 0) {
        var recovered = filters.map(function(f: Record<string, unknown>) {
          return { ...(f.filter_data as Record<string, unknown>), _id: f.id, name: f.name };
        });
        (window as Record<string, unknown>).savedFilters = recovered;
        localStorage.setItem('bj_saved_filters', JSON.stringify(recovered));
        console.log('[sync] Recovered', filters.length, 'filters from user_filters table');
      }
    } catch (e: unknown) { reportError('sync:table may not exist', e); }
  }

  if (missing.includes('tuning')) {
    try {
      var tuningResult = await (sb as SupabaseClient).from('user_tuning')
        .select('tuning_data').eq('user_id', currentUser.id).single();
      var tuningData = tuningResult.data as Record<string, unknown> | null;
      if (tuningData?.tuning_data && Object.keys(tuningData.tuning_data as Record<string, unknown>).length > 0) {
        var td = tuningData.tuning_data as TuningSettings;
        tuningSettings = td;
        localStorage.setItem('bj_tuning', JSON.stringify(td));
        tuningLocExclPills = td.locationExcludes || [];
        tuningTitleExclPills = td.titleExcludes || [];
        tuningCoExclPills = td.companyExcludes || [];
        tuningIndExclPills = td.industryExcludes || [];
        levelHierarchy = td.levelHierarchy || [];
        console.log('[sync] Recovered tuning from user_tuning table');
      }
    } catch (e: unknown) { reportError('sync:table may not exist', e); }
  }

  if (missing.includes('saved_filters') && typeof renderSavedFilters === 'function') {
    try { renderSavedFilters(); } catch (e: unknown) { reportError('sync:sync', e); }
  }
  if (missing.includes('resumes') && typeof renderResumes === 'function') {
    try { renderResumes(); } catch (e: unknown) { reportError('sync:sync', e); }
  }

  console.log('[sync] Health check recovery complete');
}

window.syncHealthCheck = syncHealthCheck;

// CS-P1-004 FE-005: Register sync exports with BJ namespace
(function(): void {
  (['syncHealthCheck'] as const).forEach(function(name) {
    var fn = (window as Record<string, unknown>)[name];
    if (typeof fn === 'function') {
      (window.BJ as Record<string, unknown>)[name] = fn;
      window.BJ._registry[name] = { module: 'sync', registered: Date.now() };
    }
  });
})();


// === js/fingerprint.ts ===
/**
 * Brilliant Jobs — Browser Fingerprint Module
 * CS-P1-015: TypeScript strict mode
 */

(function(): void {
  'use strict';

  function fnv1a(str: string): string {
    var hash = 0x811c9dc5;
    for (var i = 0; i < str.length; i++) {
      hash ^= str.charCodeAt(i);
      hash = (hash * 0x01000193) >>> 0;
    }
    return hash.toString(16).padStart(8, '0');
  }

  function getComponents(): string[] {
    var c: string[] = [];
    var nav = window.navigator || ({} as Navigator);
    var screen = window.screen || ({} as Screen);

    c.push(nav.userAgent || '');
    c.push(nav.language || '');
    c.push((nav.languages || []).join(','));

    c.push(screen.width + 'x' + screen.height);
    c.push(String(screen.colorDepth || ''));
    c.push(String(screen.pixelDepth || ''));

    try { c.push(Intl.DateTimeFormat().resolvedOptions().timeZone); } catch (_e) { c.push(''); }
    c.push(String(new Date().getTimezoneOffset()));

    c.push(nav.platform || '');
    c.push(String(nav.hardwareConcurrency || ''));
    c.push(String(nav.maxTouchPoints || 0));
    c.push(String((nav as Navigator & { deviceMemory?: number }).deviceMemory || ''));

    try {
      var canvas = document.createElement('canvas');
      var gl = canvas.getContext('webgl') || canvas.getContext('experimental-webgl');
      if (gl && gl instanceof WebGLRenderingContext) {
        var ext = gl.getExtension('WEBGL_debug_renderer_info');
        if (ext) {
          c.push(gl.getParameter(ext.UNMASKED_VENDOR_WEBGL) || '');
          c.push(gl.getParameter(ext.UNMASKED_RENDERER_WEBGL) || '');
        }
      }
    } catch (_e) { c.push('no-webgl'); }

    try {
      var cv = document.createElement('canvas');
      cv.width = 200; cv.height = 50;
      var ctx = cv.getContext('2d');
      if (ctx) {
        ctx.textBaseline = 'top';
        ctx.font = '14px Arial';
        ctx.fillStyle = '#f60';
        ctx.fillRect(0, 0, 100, 25);
        ctx.fillStyle = '#069';
        ctx.fillText('BJ-fp-2025', 2, 15);
        ctx.fillStyle = 'rgba(102, 204, 0, 0.7)';
        ctx.fillText('BJ-fp-2025', 4, 17);
        c.push(cv.toDataURL().substring(0, 100));
      }
    } catch (_e) { c.push('no-canvas'); }

    c.push(String((nav.plugins || []).length));
    c.push(String(nav.doNotTrack || ''));
    c.push(String(nav.cookieEnabled));

    return c;
  }

  function generateFingerprint(): string {
    var components = getComponents();
    var raw = components.join('||');
    var h1 = fnv1a(raw);
    var h2 = fnv1a(raw + '::salt::bj2025');
    return 'fp-' + h1 + h2;
  }

  window.bjFingerprint = {
    generate: generateFingerprint,
    components: getComponents
  };

  try {
    var fp = generateFingerprint();
    sessionStorage.setItem('bj_fingerprint', fp);
  } catch (_e) { /* privacy mode */ }
})();


// === js/tier-gating.ts ===
// ============================================================
// Tier Gating Module — Phase 7 reusable tier gate component
// CS-P1-015: TypeScript strict mode
// ============================================================

var TIER_GATES: Record<TierFeature, TierGateConfig> = {
  archive_storage:    { free: 2097152, starter: 10485760, pro: 52428800 },
  archive_retention:  { free: 30, starter: 90, pro: Infinity },
  max_resumes:        { free: 3, starter: 10, pro: Infinity },
  max_versions:       { free: 1, starter: 5, pro: Infinity },
  score_sparkline:    { free: false, starter: 10, pro: Infinity },
  level_fit:          { free: false, starter: true, pro: true },
  pipeline_stats:     { free: false, starter: 'basic', pro: 'full' },
  job_log:            { free: false, starter: 10, pro: Infinity },
  ai_scoring:         { free: false, starter: false, pro: true }
};

function getUserTier(): TierName {
  if (typeof _userPricing !== 'undefined' && _userPricing && _userPricing.tier) {
    return _userPricing.tier;
  }
  if (typeof currentUser !== 'undefined' && currentUser?.user_metadata?.plan) {
    return currentUser.user_metadata.plan as TierName;
  }
  return 'free';
}

function canAccess(feature: TierFeature): TierGateValue {
  var tier = getUserTier();
  var gate = TIER_GATES[feature];
  if (!gate) return true;
  var val = gate[tier];
  if (val === false) return false;
  if (val === true || val === Infinity) return true;
  return val;
}

function requiredTier(feature: TierFeature): TierName {
  var gate = TIER_GATES[feature];
  if (!gate) return 'free';
  if (gate.free !== false) return 'free';
  if (gate.starter !== false) return 'starter';
  return 'pro';
}

window.showTierGate = function(el: HTMLElement, minTier: TierName, message?: string): void {
  if (!el) return;
  el.style.position = 'relative';

  var existing = el.querySelector('.tier-gate-overlay');
  if (existing) existing.remove();

  var tierNames: Record<string, string> = { starter: 'Starter', pro: 'Pro' };
  var overlay = document.createElement('div');
  overlay.className = 'tier-gate-overlay';
  overlay.style.cssText = 'position:absolute;inset:0;background:rgba(15,17,23,0.85);backdrop-filter:blur(4px);display:flex;flex-direction:column;align-items:center;justify-content:center;z-index:10;border-radius:inherit;';
  overlay.innerHTML = `
    <svg viewBox="0 0 24 24" width="24" height="24" fill="none" stroke="var(--warm)" stroke-width="2" style="margin-bottom:8px;"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>
    <div style="font-size:12px;font-weight:600;color:var(--text);margin-bottom:4px;">${message || (tierNames[minTier] || 'Upgrade') + ' plan required'}</div>
    <button class="btn btn-sm btn-primary" onclick="event.stopPropagation();showPage('subscription');" style="font-size:10px;padding:4px 14px;margin-top:6px;">Upgrade to ${tierNames[minTier] || 'Pro'}</button>
  `;
  el.appendChild(overlay);
};

window.removeTierGate = function(el: HTMLElement): void {
  if (!el) return;
  var overlay = el.querySelector('.tier-gate-overlay');
  if (overlay) overlay.remove();
};

function applyMetricsTierGating(): void {
  var tier = getUserTier();

  if (tier === 'free') {
    var sparkEl = document.getElementById('metrics-sparkline');
    if (sparkEl && sparkEl.parentElement) {
      window.showTierGate(sparkEl.parentElement, 'starter', 'Score history requires Starter plan');
    }
  }

  if (tier === 'free') {
    var levelEl = document.getElementById('metrics-level-chart');
    if (levelEl && levelEl.closest('.stats-chart-card')) {
      window.showTierGate(levelEl.closest('.stats-chart-card') as HTMLElement, 'starter', 'Level fit analysis requires Starter plan');
    }
  }

  if (tier === 'free') {
    var funnelEl = document.getElementById('metrics-funnel-chart');
    if (funnelEl && funnelEl.closest('.stats-chart-card')) {
      window.showTierGate(funnelEl.closest('.stats-chart-card') as HTMLElement, 'starter', 'Pipeline analytics requires Starter plan');
    }
  }

  if (tier === 'free') {
    var logEl = document.getElementById('metrics-usage-log');
    if (logEl) window.showTierGate(logEl, 'starter', 'Application log requires Starter plan');
  }
}

function applyArchiveTierGating(): void {
  // Archive gating is mostly server-side (check_resume_limits)
}

var _origLoadResumeMetrics = window.loadResumeMetrics;
if (_origLoadResumeMetrics) {
  window.loadResumeMetrics = async function(): Promise<void> {
    await _origLoadResumeMetrics!();
    applyMetricsTierGating();
  };
}

window.canAccessFeature = canAccess;
window.getUserTier = getUserTier;
window.requiredTierFor = requiredTier;

// CS-P1-004 FE-005: Register tier-gating exports with BJ namespace
(function(): void {
  (['canAccessFeature', 'getUserTier', 'removeTierGate', 'requiredTierFor', 'showTierGate'] as const).forEach(function(name) {
    var fn = (window as Record<string, unknown>)[name];
    if (typeof fn === 'function') {
      (window.BJ as Record<string, unknown>)[name] = fn;
      window.BJ._registry[name] = { module: 'tier-gating', registered: Date.now() };
    }
  });
})();


// === js/lazy-loader.ts ===
// ============================================================
// CS-016 FIX-10: Lazy Loader — Dynamic script chunk loading
// CS-P1-015: TypeScript strict mode
// ============================================================

(function(): void {
  'use strict';

  var _loaded: Record<string, boolean> = {};
  var _loading: Record<string, Promise<void>> = {};
  var _version: string = typeof BJ_VERSION !== 'undefined' ? BJ_VERSION : 'v0';

  function bjLoadChunk(chunkName: ChunkName): Promise<void> {
    if (_loaded[chunkName]) {
      return Promise.resolve();
    }
    if (_loading[chunkName]) {
      return _loading[chunkName];
    }

    var promise = new Promise<void>(function(resolve, reject) {
      var script = document.createElement('script');
      script.src = '/dist/dashboard-' + chunkName + '.min.js?v=' + _version;
      script.async = true;
      script.onload = function(): void {
        _loaded[chunkName] = true;
        delete _loading[chunkName];
        resolve();
      };
      script.onerror = function(): void {
        delete _loading[chunkName];
        var err = new Error('Failed to load chunk: ' + chunkName);
        if (typeof reportError === 'function') reportError('lazy-loader', err);
        reject(err);
      };
      document.head.appendChild(script);
    });

    _loading[chunkName] = promise;
    return promise;
  }

  var TAB_CHUNKS: Record<TabName, ChunkName[]> = {
    'brilliant':    ['keywords'],
    'jobs':         ['keywords', 'deferred'],
    'resumes':      ['deferred', 'keywords'],
    'pipeline':     ['pipeline'],
    'tuning':       ['tuning'],
    'stats':        ['deferred'],
    'feedback':     ['deferred'],
    'ghost':        ['deferred'],
    'referrals':    ['deferred'],
    'applications': ['deferred'],
    'settings':     ['deferred'],
    'billing':      ['deferred'],
    'rewrite':      ['deferred'],
    'apply':        ['deferred'],
    'chat':         ['deferred'],
    'merch':        ['deferred'],
    'surveys':      ['deferred'],
  };

  function bjEnsureTab(tabName: TabName): Promise<void[]> {
    var chunks = TAB_CHUNKS[tabName] || [];
    if (chunks.length === 0) return Promise.resolve([]);

    var promises: Promise<void>[] = [];
    for (var i = 0; i < chunks.length; i++) {
      var chunk = chunks[i];
      if (chunk) promises.push(bjLoadChunk(chunk));
    }
    return Promise.all(promises);
  }

  function bjPreloadChunks(chunkNames: ChunkName[]): void {
    var doPreload = function(): void {
      for (var i = 0; i < chunkNames.length; i++) {
        var chunk = chunkNames[i];
        if (chunk) bjLoadChunk(chunk);
      }
    };

    if (typeof requestIdleCallback === 'function') {
      requestIdleCallback(doPreload, { timeout: 3000 });
    } else {
      setTimeout(doPreload, 2000);
    }
  }

  _loaded['shell'] = true;
  _loaded['feed'] = true;

  window.bjLoadChunk = bjLoadChunk;
  window.bjEnsureTab = bjEnsureTab as unknown as (tabName: TabName) => Promise<void>;
  window.bjPreloadChunks = bjPreloadChunks;
})();

// CS-P1-004 FE-005: Register lazy-loader exports with BJ namespace
(function(): void {
  (['bjEnsureTab', 'bjLoadChunk', 'bjPreloadChunks'] as const).forEach(function(name) {
    var fn = (window as Record<string, unknown>)[name];
    if (typeof fn === 'function') {
      (window.BJ as Record<string, unknown>)[name] = fn;
      window.BJ._registry[name] = { module: 'lazy-loader', registered: Date.now() };
    }
  });
})();


// === js/tab-guard.js ===
/**
 * CS-015: FIX-09 (FE-002) Error Boundaries + FIX-15 (FE-003) Skeleton Loaders
 * 
 * bjTabGuard — wraps tab initialization with error catching + fallback UI
 * bjSkeleton — shows/hides skeleton loading states per tab
 * 
 * Usage:
 *   bjTabGuard('stats', () => initStatsPage());
 *   bjSkeleton.show('jobs');
 *   bjSkeleton.hide('jobs');
 */

(function() {
  'use strict';

  // ─── Error Boundary ───────────────────────────────────────

  /**
   * Wrap a tab initialization function with error boundary.
   * On error: shows fallback UI with error message + retry button.
   * On success: hides skeleton, shows content.
   */
  window.bjTabGuard = function bjTabGuard(tabName, initFn) {
    try {
      var result = initFn();
      // Handle async init functions (Promises)
      if (result && typeof result.then === 'function') {
        result.then(function() {
          bjSkeleton.hide(tabName);
        }).catch(function(err) {
          _showTabError(tabName, err);
        });
      } else {
        bjSkeleton.hide(tabName);
      }
    } catch (err) {
      _showTabError(tabName, err);
    }
  };

  function _showTabError(tabName, err) {
    var page = document.getElementById('page-' + tabName);
    if (!page) return;

    // Report to PostHog
    if (window.bjError) {
      window.bjError('tab-crash:' + tabName, err);
    } else if (window.posthog) {
      posthog.capture('tab_crash', { tab: tabName, error: String(err) });
    }

    // Hide skeleton if present
    var skel = page.querySelector('.bj-tab-skeleton');
    if (skel) skel.style.display = 'none';

    // Check if fallback already exists
    var existing = page.querySelector('.bj-tab-error');
    if (existing) {
      existing.style.display = 'flex';
      return;
    }

    // Create fallback UI
    var fallback = document.createElement('div');
    fallback.className = 'bj-tab-error';
    fallback.setAttribute('role', 'alert');
    fallback.innerHTML =
      '<div class="bj-tab-error-icon">⚠️</div>' +
      '<h3 class="bj-tab-error-title">Something went wrong</h3>' +
      '<p class="bj-tab-error-msg">This section encountered an error while loading. ' +
        'Your other tabs are still working fine.</p>' +
      '<p class="bj-tab-error-detail" style="font-size:11px;color:var(--text-dim);margin:4px 0 12px;">' +
        (err && err.message ? err.message : String(err)) + '</p>' +
      '<button class="btn btn-primary btn-sm bj-tab-retry" type="button">Try again</button>';

    // Retry button: reload the page as a clean reset for the tab
    fallback.querySelector('.bj-tab-retry').addEventListener('click', function() {
      fallback.style.display = 'none';
      // Re-trigger the tab click to re-init
      var navItem = document.querySelector('.nav-item[data-page="' + tabName + '"]');
      if (navItem) navItem.click();
    });

    page.insertBefore(fallback, page.firstChild);
  }


  // ─── Skeleton Loaders ─────────────────────────────────────

  var _skeletonConfig = {
    'brilliant': { rows: 3, type: 'card' },
    'setup':     { rows: 4, type: 'form' },
    'jobs':      { rows: 8, type: 'table' },
    'tuning':    { rows: 5, type: 'form' },
    'resumes':   { rows: 4, type: 'card' },
    'applications': { rows: 5, type: 'table' },
    'notifications': { rows: 6, type: 'list' },
    'ghost':     { rows: 3, type: 'card' },
    'stats':     { rows: 3, type: 'chart' },
    'settings':  { rows: 5, type: 'form' },
    'subscription': { rows: 3, type: 'card' },
    'feedback':  { rows: 4, type: 'card' },
    'referrals': { rows: 4, type: 'card' },
  };

  function _buildSkeleton(type, rows) {
    var html = '<div class="bj-tab-skeleton" aria-label="Loading content" role="status">';
    for (var i = 0; i < rows; i++) {
      switch (type) {
        case 'table':
          html += '<div class="bj-skel-row">' +
            '<div class="skel-line" style="width:5%;height:14px;"></div>' +
            '<div class="skel-line" style="width:30%;"></div>' +
            '<div class="skel-line" style="width:20%;"></div>' +
            '<div class="skel-line" style="width:15%;"></div>' +
            '<div class="skel-line" style="width:12%;"></div>' +
          '</div>';
          break;
        case 'card':
          html += '<div class="bj-skel-card">' +
            '<div class="skel-line" style="width:60%;height:16px;margin-bottom:10px;"></div>' +
            '<div class="skel-line" style="width:90%;"></div>' +
            '<div class="skel-line" style="width:75%;"></div>' +
          '</div>';
          break;
        case 'form':
          html += '<div class="bj-skel-form-row">' +
            '<div class="skel-line" style="width:120px;height:14px;"></div>' +
            '<div class="skel-line" style="width:100%;height:36px;border-radius:6px;"></div>' +
          '</div>';
          break;
        case 'chart':
          html += '<div class="bj-skel-chart">' +
            '<div class="skel-line" style="width:40%;height:18px;margin-bottom:12px;"></div>' +
            '<div class="skel-line" style="width:100%;height:120px;border-radius:8px;"></div>' +
          '</div>';
          break;
        case 'list':
          html += '<div class="bj-skel-list-item">' +
            '<div class="skel-line" style="width:24px;height:24px;border-radius:50%;flex-shrink:0;"></div>' +
            '<div style="flex:1;">' +
              '<div class="skel-line" style="width:65%;margin-bottom:6px;"></div>' +
              '<div class="skel-line" style="width:45%;height:10px;"></div>' +
            '</div>' +
          '</div>';
          break;
      }
    }
    html += '</div>';
    return html;
  }

  window.bjSkeleton = {
    /**
     * Show skeleton loader for a tab. Injects skeleton HTML if not already present.
     */
    show: function(tabName) {
      var page = document.getElementById('page-' + tabName);
      if (!page) return;

      var config = _skeletonConfig[tabName] || { rows: 4, type: 'card' };
      var existing = page.querySelector('.bj-tab-skeleton');

      if (existing) {
        existing.style.display = '';
      } else {
        // Insert skeleton at top of page
        var wrapper = document.createElement('div');
        wrapper.innerHTML = _buildSkeleton(config.type, config.rows);
        var skel = wrapper.firstChild;
        page.insertBefore(skel, page.firstChild);
      }

      // Hide real content temporarily
      var children = page.children;
      for (var i = 0; i < children.length; i++) {
        if (!children[i].classList.contains('bj-tab-skeleton') &&
            !children[i].classList.contains('bj-tab-error')) {
          children[i].dataset.bjHidden = children[i].style.display;
          children[i].style.display = 'none';
        }
      }
    },

    /**
     * Hide skeleton loader and restore real content.
     */
    hide: function(tabName) {
      var page = document.getElementById('page-' + tabName);
      if (!page) return;

      var skel = page.querySelector('.bj-tab-skeleton');
      if (skel) skel.style.display = 'none';

      // Restore real content
      var children = page.children;
      for (var i = 0; i < children.length; i++) {
        if (children[i].dataset.bjHidden !== undefined) {
          children[i].style.display = children[i].dataset.bjHidden;
          delete children[i].dataset.bjHidden;
        }
      }
    }
  };

})();

// CS-P1-004 FE-005: Register tab-guard exports with BJ namespace
(function() {
  ['bjSkeleton','bjTabGuard'].forEach(function(name) {
    if (typeof window[name] === 'function') {
      window.BJ[name] = window[name];
      window.BJ._registry[name] = { module: 'tab-guard', registered: Date.now() };
    }
  });
})();


// === js/app.js ===
// [BJ] Dashboard v7.22 loaded
console.log('[BJ] Dashboard ' + BJ_VERSION + ' loaded');
// BJ_VERSION is defined in js/version.js (single source of truth)
// version.js auto-populates #nav-version and .bj-version elements

// CS-P1-007 DS1-6: Page metadata for virtual $pageview events (all 14 pages)
var _bjPageTitles = {
  brilliant: 'Get Started', setup: 'Setup', jobs: 'Jobs Feed', tuning: 'Search Tuning',
  resumes: 'Resumes', applications: 'My Applications', notifications: 'Notifications',
  ghost: 'Ghost Monitor', stats: 'Stats', referrals: 'Referrals', settings: 'Settings',
  subscription: 'Subscription', feedback: 'Feedback', pipeline: 'Pipeline'
};
var _bjPageSections = {
  brilliant: 'onboarding', setup: 'onboarding', jobs: 'search', tuning: 'search',
  resumes: 'search', applications: 'tracking', notifications: 'tracking',
  ghost: 'intelligence', stats: 'intelligence', referrals: 'growth',
  settings: 'account', subscription: 'account', feedback: 'account', pipeline: 'tracking'
};

// Auth
async function init() {
  const { data: { session } } = await sb.auth.getSession();
  if (!session?.user) { window.location.href = '/'; return; }
  currentUser = session.user;
  // CS-003 + CS-P1-007 DS1-4: PostHog identity resolution — identify user post-login
  if (window.posthog && currentUser) {
    posthog.identify(currentUser.id, {
      email: currentUser.email,
      created_at: currentUser.created_at,
    });
    // DS1-4: $set_once for immutable first-seen props (won't overwrite on subsequent logins)
    posthog.setPersonProperties({}, {
      first_seen_at: currentUser.created_at,
      signup_source: 'dashboard',
    });
    // DS1-4: Surface super property — all dashboard events tagged
    posthog.register({ bj_surface: 'dashboard' });
  }
  // Persist account flag for landing page segment detection (survives logout)
  localStorage.setItem('bj_has_account', 'true');

// Pre-warm static ref table caches (v3.84)
if (typeof prewarmRefCaches === 'function') prewarmRefCaches();

// Error recovery & offline resilience (v3.87)
if (typeof initOfflineDetection === 'function') initOfflineDetection();
if (typeof initGlobalErrorHandlers === 'function') initGlobalErrorHandlers();

// Session management hardening (v3.90)
if (typeof initSessionManagement === 'function') initSessionManagement();
  let profile = null;
  try {
    const p = await safeQuery(() => sb.from('profiles').select('approved,cohort_id,plan,role').eq('id', currentUser.id).single(), { label: 'app:profiles', fallback: null });
    profile = p;
    if (!p?.approved) { window.location.href = '/?pending=1'; return; }
    currentUser._cohortId = p.cohort_id || null;
    window._bjUserPlan = p.plan || 'free';
    window._bjUserRole = p.role || 'user';
  } catch (e) { if (typeof toastError === 'function') toastError('Failed to load your profile. Please refresh the page.'); }
  $('#auth-gate').style.display = 'none';
  $('#app').style.display = 'flex';
  // Referral attribution — check if new user came via referral link (Phase 4 v5.10)
  try { await processReferralAttribution(currentUser); } catch(e) { reportError('app', e); console.warn('[Referral] Attribution check skipped:', e.message); }
  // Show admin nav immediately — profile already fetched, no extra round trip
  window._isAdmin = !!(profile && profile.role === 'admin');
  if (window._isAdmin) {
    var navAdmin = document.getElementById('nav-admin');
    if (navAdmin) { navAdmin.style.display = ''; console.log('[Admin] \u2713 Nav shown'); }
    // Show survey analytics tab (admin-only) in Feedback page
    var surveyTab = document.getElementById('fb-tab-surveys');
    if (surveyTab) surveyTab.style.display = '';
  }
  // Re-apply active page (tab restore ran while #app was hidden)
  const activeTab = localStorage.getItem('bj_active_tab');
  if (activeTab && $(`#page-${activeTab}`)) {
    $$('.page').forEach(p => p.classList.remove('active'));
    $(`#page-${activeTab}`).classList.add('active');
    $$('.nav-item').forEach(n => n.classList.toggle('active', n.dataset.page === activeTab));
  }
  $('#nav-email').textContent = currentUser.email;
  $('#nav-avatar').textContent = currentUser.email.charAt(0).toUpperCase();
  // Update nav tier badge based on profile role/plan
  const navPlanEl = document.querySelector('.nav-user-plan');
  if (navPlanEl && profile) {
    if (profile.role === 'admin') {
      navPlanEl.textContent = 'ADMIN';
      navPlanEl.style.color = 'var(--warm)';
      navPlanEl.style.fontWeight = '700';
      navPlanEl.style.letterSpacing = '1px';
    } else if ((profile.plan || 'free') === 'pro') {
      navPlanEl.textContent = 'Pro Plan';
      navPlanEl.style.color = 'var(--accent)';
      navPlanEl.style.fontWeight = '600';
    } else if ((profile.plan || 'free') === 'enterprise') {
      navPlanEl.textContent = 'Enterprise';
      navPlanEl.style.color = 'var(--purple)';
      navPlanEl.style.fontWeight = '600';
    } else {
      navPlanEl.textContent = 'Free Plan';
    }
  }
  // Sync user data from Supabase → localStorage on login
  await loadUserData(currentUser.id);
  // Session analytics — Phase B
  const bjSessionId = await initSession();
  if (bjSessionId && window.posthog) {
    posthog.register({
      bj_session_id: bjSessionId,
      bj_cohort_id: currentUser._cohortId || null,
      bj_plan_id: window._bjUserPlan || 'free',
      bj_surface: 'dashboard'
    });
  }
  // CS-P1-007 DS1-6: Initial virtual $pageview on dashboard load
  if (window.posthog) {
    var _initPage = localStorage.getItem('bj_active_tab') || 'brilliant';
    var _initTitle = _bjPageTitles[_initPage] || _initPage;
    posthog.capture('$pageview', {
      $current_url: window.location.origin + '/dashboard.html#' + _initPage,
      $pathname: '/dashboard.html#' + _initPage,
      title: 'Brilliant Jobs — ' + _initTitle,
      bj_page: _initPage,
      bj_page_section: _bjPageSections[_initPage] || 'other',
      bj_initial_load: true,
    });
  }
  // Re-init admin page if it was the active tab (tab restore runs before auth)
  // Admin moved to /admin page (v6.26)
  
  // Q24-Q25: Load saved filters and tuning from Supabase (fallback to localStorage)
  const userId = session?.user?.id;
  
  // Load filters from Supabase
  let filtersFromCloud = false;
  if (userId) {
    const cloudFilters = await safeQuery(() => sb.from('user_filters').select('*').eq('user_id', userId).order('sort_order'), { label: 'app:user_filters', fallback: [] });
    if (cloudFilters && cloudFilters.length > 0) {
      savedFilters = cloudFilters.map(f => ({ ...f.filter_data, _id: f.id, name: f.name }));
      filtersFromCloud = true;
    }
  }
  if (!filtersFromCloud) {
    savedFilters = safeReadLS('bj_saved_filters', []);
    // Migrate localStorage filters to Supabase on first load
    if (userId && savedFilters.length > 0 && !localStorage.getItem('bj_filters_migrated')) {
      for (let i = 0; i < savedFilters.length; i++) {
        const f = savedFilters[i];
        var { error: fltErr } = await sb.from('user_filters').insert({
          user_id: userId,
          name: f.name || 'Untitled',
          filter_data: f,
          sort_order: i,
        });
        if (fltErr) { reportError('app:filter-migrate', fltErr); break; }
      }
      localStorage.setItem('bj_filters_migrated', '1');
      showToast('Your saved searches are now synced to the cloud.', { type: 'success', duration: 5000 });
    }
  }

  // v7.21: Re-apply progressive nav now that savedFilters is loaded from DB
  // initOnboarding() runs synchronously at parse time before this async fetch completes,
  // so nav items were always dimmed for users with saved filters.
  {
    let _step = getOnboardingStep();
    if (_step < 1 && resumes && resumes.length > 0) { updateOnboardingStep(1); _step = 1; }
    if (_step < 2 && savedFilters && savedFilters.length > 0) { updateOnboardingStep(2); _step = 2; }
    if (_step < 3 && localStorage.getItem('bj_first_search_done')) { updateOnboardingStep(3); _step = 3; }
    if (_step < 4 && localStorage.getItem('bj_pipeline_used')) { updateOnboardingStep(4); _step = 4; }
    applyProgressiveNav(_step);
  }

  // Block 7: Check for pending pills from city page conversion
  try {
    var pendingPills = safeReadLS('bj_pending_pills', []);
    if (pendingPills.length > 0) {
      localStorage.removeItem('bj_pending_pills');
      // Apply to active filter (or first filter, or create new)
      var target = currentFilter || (savedFilters && savedFilters.length > 0 ? savedFilters[0] : null);
      if (target) {
        var pillsKey = target.pills ? 'pills' : 'keywords';
        if (!target[pillsKey]) target[pillsKey] = [];
        pendingPills.forEach(function(pp) {
          var pillType = pp.type === 'title' ? 'TITLE' : pp.type === 'skill' ? 'SKILLS' : pp.type === 'industry' ? 'INDUSTRY' : 'KEYWORD';
          var exists = target[pillsKey].some(function(p) { return p.type === pillType && p.value === pp.value; });
          if (!exists) {
            target[pillsKey].push({ type: pillType, value: pp.value, _from: 'city_page' });
          }
        });
        localStorage.setItem('bj_saved_filters', JSON.stringify(savedFilters));
        var names = pendingPills.map(function(p) { return '"' + p.value + '"'; }).join(', ');
        showToast('Added ' + names + ' to your search filters', { type: 'success', duration: 5000 });
        if (window.posthog) posthog.capture('pending_pills_applied', { count: pendingPills.length, pills: pendingPills });
      }
    }
  } catch(e) { reportError('app', e); console.warn('[pills] Pending pill apply failed:', e.message); }
  
  // Load tuning from Supabase
  // First: normalize any legacy WHEN pills in saved filters
  let whenNormDirty = false;
  savedFilters.forEach(sf => {
    if (sf.whenPills && sf.whenPills.length > 0) {
      sf.whenPills.forEach(pill => {
        if (pill.values && pill.values.length > 0) {
          const norm = typeof normalizeWhenValue === 'function' ? normalizeWhenValue(pill.values[0]) : null;
          if (norm && norm.label !== pill.values[0]) {
            pill.values[0] = norm.label;
            whenNormDirty = true;
          }
        }
      });
    }
  });
  if (whenNormDirty) {
    if (filtersFromCloud && userId) {
      // Persist normalized values back to cloud
      for (let i = 0; i < savedFilters.length; i++) {
        const sf = savedFilters[i];
        if (sf._id) {
          sb.from('user_filters').update({ filter_data: sf }).eq('id', sf._id).then(() => {});
        }
      }
    }
    saveUserData('bj_saved_filters', JSON.stringify(savedFilters));
  }

  let tuningFromCloud = false;
  if (userId) {
    const cloudTuning = await safeQuery(() => sb.from('user_tuning').select('tuning_data').eq('user_id', userId).single(), { label: 'app:user_tuning', fallback: null });
    if (cloudTuning?.tuning_data && Object.keys(cloudTuning.tuning_data).length > 0) {
      tuningSettings = cloudTuning.tuning_data;
      tuningFromCloud = true;
    }
  }
  if (!tuningFromCloud) {
    tuningSettings = safeReadLS('bj_tuning', {});
    // Migrate to Supabase
    if (userId && Object.keys(tuningSettings).length > 0 && !localStorage.getItem('bj_tuning_migrated')) {
      var { error: tunErr } = await sb.from('user_tuning').upsert({
        user_id: userId,
        tuning_data: tuningSettings,
      }, { onConflict: 'user_id' });
      if (tunErr) reportError('app:tuning-migrate', tunErr);
      else localStorage.setItem('bj_tuning_migrated', '1');
    }
  }
  
  tuningLocExclPills = tuningSettings.locationExcludes || [];
  tuningTitleExclPills = tuningSettings.titleExcludes || [];
  tuningCoExclPills = tuningSettings.companyExcludes || [];
  tuningIndExclPills = tuningSettings.industryExcludes || [];
  levelHierarchy = tuningSettings.levelHierarchy || [];
  hiddenJobIds = safeReadLS('bj_hidden_jobs', []);
  // Pipeline now loaded from Supabase (Ghost Build Phase 1)
  // savedJobIds and appliedJobIds are populated by initPipeline()
  savedJobIds = [];
  appliedJobIds = [];
  resumes = (await readPiiData('bj_resumes')) || [];
  // Safety net: if resumes still empty after loadUserData, try direct cloud fetch (v4.33)
  if (resumes.length === 0 && userId) {
    try {
      const prof = await safeQuery(() => sb.from('profiles').select('user_data').eq('id', userId).single(), { label: 'app:profiles', fallback: null });
      const cloudResumes = prof?.user_data?.resumes;
      if (Array.isArray(cloudResumes) && cloudResumes.length > 0) {
        resumes = cloudResumes;
        saveUserData('bj_resumes', JSON.stringify(resumes));
        console.log('[sync] Resume recovery: restored', resumes.length, 'resumes from cloud');
      }
    } catch(e) { reportError('app', e); console.warn('[sync] Resume recovery failed:', e.message); }
  }
  // Check for resumes missing storagePath and attempt upload from IndexedDB (v4.46)
  if (resumes.length > 0 && currentUser) {
    var needsStorageSync = resumes.filter(function(r) { return !r.storagePath && !r.archived; });
    if (needsStorageSync.length > 0) {
      console.log('[resume-storage] ' + needsStorageSync.length + ' resumes need Storage upload');
      needsStorageSync.forEach(async function(r) {
        try {
          var file = await bjFileStore.get(r.id);
          if (file) {
            var path = currentUser.id + '/' + r.id + '_' + (r.fileName || 'resume').replace(/[^a-zA-Z0-9._-]/g, '_');
            var { error } = await sb.storage.from('resumes').upload(path, file, { cacheControl: '3600', upsert: true, contentType: file.type || 'application/octet-stream' });
            if (!error) {
              var idx = resumes.findIndex(function(x) { return x.id === r.id; });
              if (idx >= 0) { resumes[idx].storagePath = path; saveResumes(); }
              console.log('[resume-storage] Backfilled', path);
            }
          }
        } catch(e) { reportError('app:silent', e); }
      });
    }
  }
  // Cloud sync is now live via user_filters + user_tuning tables
  // Q23: Populate global rules crosslink banner
  const grBanner = document.getElementById('global-rules-banner');
  const grSummary = document.getElementById('gr-summary');
  if (grBanner && grSummary) {
    const parts = [];
    if (tuningSettings.locationExcludes?.length) parts.push(tuningSettings.locationExcludes.length + ' excluded locations');
    if (tuningSettings.titleExcludes?.length) parts.push(tuningSettings.titleExcludes.length + ' excluded titles');
    if (tuningSettings.companyExcludes?.length) parts.push(tuningSettings.companyExcludes.length + ' excluded companies');
    if (tuningSettings.levelHierarchy?.length) parts.push(tuningSettings.levelHierarchy.length + ' levels');
    if (parts.length) {
      grSummary.textContent = parts.join(', ');
      grBanner.style.display = '';
    }
  }
  // Initialize Supabase pipeline (migrate localStorage → Supabase on first run)
  if (typeof initPipeline === 'function') await initPipeline();
  // Overlay Pipeline S2: migrate localStorage pipeline → new pipeline table (one-time)
  if (typeof PipelineMigration !== 'undefined' && !PipelineMigration.hasRun()) {
    PipelineMigration.run(window._sb || sb, currentUser.id).catch(function(e) {
      console.warn('[BJ] pipeline-migration failed:', e);
    });
  }
  // Trigger sparkle flourish
  setTimeout(() => { $('#nav-brand').classList.add('sparkle-active'); }, 100);
  // Initialize billing (credit balance, pricing, payment return check)
  if (typeof initBilling === 'function') initBilling();
  // Run unified sync health check — recovers any missing localStorage domains from cloud
  if (typeof syncHealthCheck === 'function') {
    setTimeout(function() { syncHealthCheck(); }, 500);
  }
  if (typeof loadStats === 'function') loadStats();
  checkExtensionStatus();
  if (typeof loadCollections === 'function') loadCollections();
  // Initialize Notification Center (Session 2 — loads state, prefs, opt-in check)
  if (typeof initNotificationCenter === 'function') initNotificationCenter();
  // Start session heartbeat
  if (bjSessionId) {
    setInterval(() => {
      if (document.visibilityState === 'visible') {
        sb.rpc('session_heartbeat', { p_session_id: bjSessionId }).then(r => { if (r.error) reportError('app:heartbeat', r.error); });
      }
    }, 5 * 60 * 1000);
  }
}

// Session analytics — create or reuse session
async function initSession() {
  const existing = sessionStorage.getItem('bj_session_id');
  if (existing) {
    sb.rpc('session_heartbeat', { p_session_id: existing }).then(r => { if (r.error) reportError('app:heartbeat-resume', r.error); });
    return existing;
  }
  const deviceType = window.innerWidth < 768 ? 'mobile' :
                     window.innerWidth < 1024 ? 'tablet' : 'desktop';
  const params = new URLSearchParams(window.location.search);
  const referralSource = params.get('utm_source') || params.get('ref') || 'direct';
  const entryPage = window.location.pathname;
  try {
    const { data: sessionId, error } = await sb.rpc('create_session', {
      p_user_id: currentUser.id,
      p_device_type: deviceType,
      p_referral_source: referralSource,
      p_entry_page: entryPage,
      p_metadata: {}
    });
    if (error) { console.error('[BJ] Session init error:', error); return null; }
    sessionStorage.setItem('bj_session_id', sessionId);
    return sessionId;
  } catch (e) {
    reportError('app', e);
    console.error('[BJ] Session init error:', e);
    return null;
  }
}

